def weeks(*titles):
    if len(titles) != 15:
        raise SystemExit("need 15 week titles")
    return [{"date": DATES[i], "title": titles[i]} for i in range(15)]

def unit(anchor, title, body, questions, eli):
    return {"id": anchor, "title": title, "body": body, "questions": questions, "eli": eli}

